catalog; verify the template publisher before installing.","sort_order":35}],"expected_resource_estimates":{"ram_estimate_min_mb":256,"ram_estimate_max_mb":2048,"ram_estimate_kind":"estimated","ram_estimate_confidence":"low","ram_estimate_basis":"Typical small self-hosted instance; workload and stored data vary.","ram_source_urls":["https://github.com/mstrhakr/network-list-sync/issues/"],"storage_estimate_min_gb":50,"storage_estimate_max_gb":500,"storage_estimate_kind":"estimated","storage_estimate_confidence":"low","storage_estimate_basis":"Typical small self-hosted instance; workload and stored data vary.","storage_source_urls":["https://github.com/mstrhakr/network-list-sync/issues/"]},"resource_estimates":{"ram":{"min_mb":128,"max_mb":512,"kind":"estimated","confidence":"low","basis":"A single Go service manages sync jobs and an embedded web UI; endpoint count drives memory use.","source_urls":["https://github.com/mstrhakr/network-list-sync#readme"]},"storage":{"min_gb":1,"max_gb":5,"kind":"estimated","confidence":"low","basis":"SQLite stores settings and sync history; number of jobs and retained history drive storage use.","source_urls":["https://github.com/mstrhakr/network-list-sync#readme"]}},"expected_docker_image_status":{"status":"published","checked_at":"2026-09-02T14:22:59.972798+00:00"},"docker_image_status":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"The project recommends its GHCR image.","source_urls":["https://github.com/mstrhakr/network-list-sync#quick-start","https://github.com/orgs/mstrhakr/packages/container/package/network-list-sync"]}}]$batch$::jsonb;
BEGIN
  FOR app_rec IN
    SELECT * FROM jsonb_to_recordset(batch) AS x(
      slug text,
      source_urls text[],
      expected_install_options jsonb,
      restored_install_options jsonb,
      expected_resource_estimates jsonb,
      resource_estimates jsonb,
      expected_docker_image_status jsonb,
      docker_image_status jsonb
    )
  LOOP
    SELECT a.id INTO v_app_id
    FROM public.self_host_apps a
    WHERE a.slug=app_rec.slug
      AND a.published IS TRUE
      AND a.self_hosting_status='self_hostable'
      AND to_jsonb(a) @> jsonb_build_object('technical_fact_status', jsonb_build_object('docker_image', app_rec.expected_docker_image_status));
    IF v_app_id IS NULL THEN
      RAISE EXCEPTION '% Docker image evidence changed since review', app_rec.slug;
    END IF;

    SELECT io.options INTO current_options
    FROM public.self_host_app_install_options io
    WHERE io.app_id=v_app_id
    FOR UPDATE;
    IF current_options IS DISTINCT FROM app_rec.expected_install_options THEN
      RAISE EXCEPTION '% install options changed since review', app_rec.slug;
    END IF;

    UPDATE public.self_host_app_resource_estimates AS r SET
      ram_estimate_min_mb=(app_rec.resource_estimates->'ram'->>'min_mb')::numeric,
      ram_estimate_max_mb=(app_rec.resource_estimates->'ram'->>'max_mb')::numeric,
      ram_estimate_kind=app_rec.resource_estimates->'ram'->>'kind',
      ram_estimate_confidence=app_rec.resource_estimates->'ram'->>'confidence',
      ram_estimate_basis=app_rec.resource_estimates->'ram'->>'basis',
      ram_source_urls=ARRAY(SELECT jsonb_array_elements_text(app_rec.resource_estimates->'ram'->'source_urls')),
      storage_estimate_min_gb=(app_rec.resource_estimates->'storage'->>'min_gb')::numeric,
      storage_estimate_max_gb=(app_rec.resource_estimates->'storage'->>'max_gb')::numeric,
      storage_estimate_kind=app_rec.resource_estimates->'storage'->>'kind',
      storage_estimate_confidence=app_rec.resource_estimates->'storage'->>'confidence',
      storage_estimate_basis=app_rec.resource_estimates->'storage'->>'basis',
      storage_source_urls=ARRAY(SELECT jsonb_array_elements_text(app_rec.resource_estimates->'storage'->'source_urls')),
      checked_at=now(),
      updated_at=now()
    WHERE r.app_id=v_app_id
      AND to_jsonb(r) @> app_rec.expected_resource_estimates
      AND r.ram_source_urls IS NOT DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(app_rec.expected_resource_estimates->'ram_source_urls'))
      AND r.storage_source_urls IS NOT DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(app_rec.expected_resource_estimates->'storage_source_urls'));
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN RAISE EXCEPTION '% resource estimates changed since review', app_rec.slug; END IF;

    UPDATE public.self_host_app_install_options AS io SET
      options=app_rec.restored_install_options,
      docker_urls=ARRAY(SELECT o->>'url' FROM jsonb_array_elements(app_rec.restored_install_options) o WHERE o->>'method'='docker' ORDER BY (o->>'sort_order')::integer),
      docker_images=ARRAY(SELECT DISTINCT o->>'image' FROM jsonb_array_elements(app_rec.restored_install_options) o WHERE o->>'method'='docker' AND nullif(o->>'image','') IS NOT NULL ORDER BY 1),
      compose_urls=ARRAY(SELECT o->>'url' FROM jsonb_array_elements(app_rec.restored_install_options) o WHERE o->>'method'='compose' ORDER BY (o->>'sort_order')::integer),
      unraid_urls=ARRAY(SELECT o->>'url' FROM jsonb_array_elements(app_rec.restored_install_options) o WHERE o->>'method'='unraid' ORDER BY (o->>'sort_order')::integer),
      source_urls=ARRAY(SELECT DISTINCT o->>'source_url' FROM jsonb_array_elements(app_rec.restored_install_options) o WHERE nullif(o->>'source_url','') IS NOT NULL ORDER BY 1),
      checked_at=now(),
      updated_at=now()
    WHERE io.app_id=v_app_id
      AND io.options=app_rec.expected_install_options;
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN RAISE EXCEPTION '% install option restore failed', app_rec.slug; END IF;

    UPDATE public.self_host_apps AS a SET
      technical_fact_status=coalesce(a.technical_fact_status,'{}'::jsonb) || jsonb_build_object('docker_image', app_rec.docker_image_status),
      updated_at=now()
    WHERE a.id=v_app_id
      AND to_jsonb(a) @> jsonb_build_object('technical_fact_status', jsonb_build_object('docker_image', app_rec.expected_docker_image_status));
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN RAISE EXCEPTION '% Docker image evidence update failed', app_rec.slug; END IF;
  END LOOP;
END
$migration$;
